CREATE OR REPLACE FUNCTION public.fn_historial_precios()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $function$
begin
    if (new.precio_compra is distinct from old.precio_compra)
       or (new.precio_venta is distinct from old.precio_venta)
       or (new.margen_ganancia is distinct from old.margen_ganancia) then
        insert into public.historial_precios
            (id_producto_color, precio_compra, precio_venta, margen_ganancia)
        values
            (new.id_producto_color, new.precio_compra, new.precio_venta, new.margen_ganancia);
    end if;
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_venta_detalle_subtotal()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $function$
begin
    new.subtotal := round(new.cantidad * new.precio, 2);
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_venta_total()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $function$
declare
    v_ids int[];
begin
    -- Recalcula la venta afectada (y la anterior si cambió de venta)
    if tg_op = 'INSERT' then
        v_ids := array[new.id_venta];
    elsif tg_op = 'DELETE' then
        v_ids := array[old.id_venta];
    else
        v_ids := array_remove(array[new.id_venta, old.id_venta], null);
    end if;

    update public.venta v
       set total_venta = coalesce((
               select sum(d.subtotal)
                 from public.venta_detalle d
                where d.id_venta = v.id_venta
           ), 0)
     where v.id_venta = any (v_ids);
    return null;
end;
$function$;

