CREATE TRIGGER trg_venta_detalle_subtotal
  BEFORE INSERT OR UPDATE OF cantidad, precio ON public.venta_detalle
  FOR EACH ROW
  EXECUTE FUNCTION public.fn_venta_detalle_subtotal();

CREATE TRIGGER trg_venta_total
  AFTER INSERT OR DELETE OR UPDATE ON public.venta_detalle
  FOR EACH ROW
  EXECUTE FUNCTION public.fn_venta_total();

