CREATE POLICY "usuario_ve_sus_ventas" ON "public"."venta"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.usuario u
  WHERE ((u.id_usuario = venta.id_usuario) AND (u.auth_id = auth.uid())))));

CREATE POLICY "usuario_ve_su_detalle" ON "public"."venta_detalle"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM (public.venta v
     JOIN public.usuario u ON ((u.id_usuario = v.id_usuario)))
  WHERE ((v.id_venta = venta_detalle.id_venta) AND (u.auth_id = auth.uid())))));

